std::shared_ptr<T> ptr1 = std::make_shared<T>(constructor_args); // create shared ownership
// Copy or assign shared_ptrs to share ownership
std::shared_ptr<T> ptr2 = ptr1; // both share ownership
// Access the managed object via * or ->
ptr1->member_function();
// Reset or release ownership
ptr2.reset(); // decreases reference count, deletes object if count reaches zero

code_example:
#include <iostream>
#include <memory>

class Widget {
public:
    Widget() { std::cout << "Widget created" << std::endl; }
    ~Widget() { std::cout << "Widget destroyed" << std::endl; }
    void display() { std::cout << "Displaying Widget" << std::endl; }
};

int main() {
    // Create a shared_ptr managing a new Widget
    auto ptr1 = std::make_shared<Widget>();
    {
        // Share ownership with another shared_ptr
        auto ptr2 = ptr1;
        ptr2->display();
        std::cout << "Reference count: " << ptr1.use_count() << std::endl;
    } // ptr2 goes out of scope here, reference count decreases
    std::cout << "Reference count after ptr2 scope: " << ptr1.use_count() << std::endl;
    // Reset ptr1, destroying the Widget if no other owners
    ptr1.reset();
    return 0;
}
